#include<stdio.h>
#include<stdlib.h>
#include<string.h>
#include<math.h>
#define D 768
#define H 12
#define L 12
#define V 50257
#define N 1024
#define F 3072
#define R 64
float*C,*W[L][12],*lb,*lg,*we,*pe,*x,*kc[L],*vc[L];
void ln(float*o,float*x,float*g,float*b){float m=0,v=0;
 for(int j=0;j<D;j++)m+=x[j];m/=D;
 for(int j=0;j<D;j++){float d=x[j]-m;v+=d*d;}
 v=sqrtf(v/D+1e-5f);for(int j=0;j<D;j++)o[j]=(x[j]-m)/v*g[j]+b[j];}
void mm(float*o,float*x,float*w,float*b,int d,int k){
 for(int j=0;j<d;j++){float s=b?b[j]:0;for(int p=0;p<k;p++)s+=x[p]*w[p*d+j];o[j]=s;}}
// Batch forward: process all positions simultaneously
void fwd_batch(int n){
 float xn[N][D],qkv[N][3*D],att[N][D],pr[N][D],xn2[N][D],h[N][F],h2[N][D];
 float kk[N][D],vv[N][D];
 for(int l=0;l<L;l++){
  // LN1
  for(int i=0;i<n;i++)ln(xn[i],x+i*D,W[l][5],W[l][4]);
  // QKV
  for(int i=0;i<n;i++)mm(qkv[i],xn[i],W[l][1],W[l][0],3*D,D);
  // Split QKV and store K,V
  for(int i=0;i<n;i++){memcpy(kk[i],qkv[i]+D,D*4);memcpy(vv[i],qkv[i]+2*D,D*4);}
  // Attention
  for(int i=0;i<n;i++)for(int hh=0;hh<H;hh++){
   float sc[N],mx=-1e9f;
   for(int j=0;j<=i;j++){float s=0;for(int d=0;d<R;d++)s+=qkv[i][hh*R+d]*kk[j][hh*R+d];s*=.125f;sc[j]=s;if(s>mx)mx=s;}
   float sm=0;for(int j=0;j<=i;j++){sc[j]=expf(sc[j]-mx);sm+=sc[j];}
   for(int d=0;d<R;d++){float s=0;for(int j=0;j<=i;j++)s+=sc[j]/sm*vv[j][hh*R+d];att[i][hh*R+d]=s;}
  }
  // c_proj + residual
  for(int i=0;i<n;i++){mm(pr[i],att[i],W[l][3],W[l][2],D,D);for(int j=0;j<D;j++)x[i*D+j]+=pr[i][j];}
  // LN2
  for(int i=0;i<n;i++)ln(xn2[i],x+i*D,W[l][7],W[l][6]);
  // MLP
  for(int i=0;i<n;i++)mm(h[i],xn2[i],W[l][9],W[l][8],F,D);
  for(int i=0;i<n;i++)for(int j=0;j<F;j++){float t=h[i][j];h[i][j]=.5f*t*(1.f+tanhf(.7978845608f*(t+.044715f*t*t*t)));}
  for(int i=0;i<n;i++){mm(h2[i],h[i],W[l][11],W[l][10],D,F);for(int j=0;j<D;j++)x[i*D+j]+=h2[i][j];}
 }
}
int main(){C=malloc(497759232);FILE*f=fopen("/app/gpt2-124M.ckpt","rb");fread(C,4,124439808,f);fclose(f);
 float*p=C;
 for(int l=0;l<L;l++){W[l][0]=p;p+=3*D;W[l][1]=p;p+=3*D*D;W[l][2]=p;p+=D;
  W[l][3]=p;p+=D*D;W[l][4]=p;p+=D;W[l][5]=p;p+=D;W[l][6]=p;p+=D;
  W[l][7]=p;p+=D;W[l][8]=p;p+=F;W[l][9]=p;p+=F*D;W[l][10]=p;p+=D;W[l][11]=p;p+=F*D;}
 lb=p;p+=D;lg=p;p+=D;pe=p;p+=N*D;we=p;p+=V*D;
 x=calloc(N*D,4);
 int toks[]={7454,2402,257,640};
 int nt=4;
 for(int i=0;i<nt;i++)for(int j=0;j<D;j++)x[i*D+j]=we[toks[i]*D+j]+pe[i*D+j];
 fwd_batch(nt);
 float xn[D];ln(xn,x+(nt-1)*D,lg,lb);
 float scores[V];for(int j=0;j<V;j++){float s=0;for(int d=0;d<D;d++)s+=xn[d]*we[j*D+d];scores[j]=s;}
 printf("batch:");
 for(int t=0;t<10;t++){int best=0;float mx=-1e9f;for(int j=0;j<V;j++)if(scores[j]>mx){mx=scores[j];best=j;}printf(" %d(%.1f)",best,mx);scores[best]=-1e9f;}
 printf("\n");
 return 0;}
